import { api } from './api.js';
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',bag:'M5 7h14l1 14H4L5 7Z M9 8V6a3 3 0 0 1 6 0v2',pin:'M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',user:'M20 21v-2a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v2 M16 5a4 4 0 1 1-8 0 4 4 0 0 1 8 0',help:'M9.1 9a3 3 0 0 1 5.8 1c0 2-3 3-3 3 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',sparkles:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z M20 2v4 M18 4h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3l-1 3-3 1-2 4 2 2v4l4 3 3-1 3 1 4-3v-4l2-2-2-4-3-1-1-3H9Z',chevrons:'m9 8 3-3 3 3 M9 16l3 3 3-3',chevron:'m8 10 4 4 4-4',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',plus:'M12 5v14 M5 12h14',arrow:'M4 12h16 M14 6l6 6-6 6',check:'m5 12 4 4L19 6',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 2',washer:'M4 2h16v20H4Z M4 7h16 M7 4.5h.01 M10 4.5h.01 M17 14a5 5 0 1 1-10 0 5 5 0 0 1 10 0 M8 14c3-3 5 3 8 0',calendar:'M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Z M7 2v4 M17 2v4 M3 10h18',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4Z m-4 10 3 3 5-5',search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',x:'m6 6 12 12 M6 18 18 6',menu:'M3 6h18 M3 12h18 M3 18h18',logout:'M10 4H4v16h6 M10 12h11 M17 8l4 4-4 4',shirt:'m8 3-6 4 3 5 3-2v11h8V10l3 2 3-5-6-4a4 4 0 0 1-8 0Z',truck:'M1 5h13v12H1z M14 9h5l4 5v3h-9 M8 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0 M21 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0',store:'M4 10v11h16V10 M2 10l3-8h14l3 8c-1 3-4 3-5 0-1 3-4 3-5 0-1 3-4 3-5 0-1 3-4 3-5 0 M9 21v-7h6v7',info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 11v6 M12 7h.01'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.sparkles}"/></svg>`;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n)||0);
const date=(d,time=false)=>d?new Date(d).toLocaleString('en-US',{month:'short',day:'numeric',...(time?{hour:'numeric',minute:'2-digit'}:{})}):'Not scheduled';
const title=s=>String(s||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const short=o=>`SW-${o.id.slice(-6).toUpperCase()}`;
const active=o=>['pending','confirmed','inprogress'].includes(o.status);
function storedValue(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
const savedLaundries=storedValue('sw.saved',[]);
const state={orders:[],partners:[],services:[],view:'overview',filter:'all',search:'',type:'all',city:localStorage.getItem('sw.city')||'',saved:Array.isArray(savedLaundries)?savedLaundries.filter(id=>typeof id==='string'):[],error:null};
let booking=null,lastFocus=null;
const role=()=>api.user?.role||'customer';
const pName=id=>state.partners.find(p=>p.id===id)?.businessName||'Your laundry partner';
const initials=n=>n?.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase()||'SW';
function hydrate(){ $$('[data-icon]').forEach(e=>{e.outerHTML=icon(e.dataset.icon);}); }
function toast(message,error=false){const el=document.createElement('div');el.className=`toast ${error?'error':''}`;el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),6500);}
function errorText(e){return [e.message,...(Array.isArray(e.details)?e.details.map(x=>`${x.field}: ${x.message}`):[])].join(' ');}
function nav(){const business=['partner','admin'].includes(role()); const items=[['overview','grid','Overview'],['orders','bag',role()==='customer'?'My orders':'Orders'],['partners','pin','Find a laundry'],['saved','heart','Saved laundries']];if(business)items.push(['business','store',role()==='admin'?'Manage partners':'My business']);$('#nav').innerHTML=items.map(([v,i,t])=>`<a class="nav-link ${state.view===v?'active':''}" href="#${v}" ${state.view===v?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${v==='orders'&&state.orders.filter(active).length?`<span class="nav-count">${state.orders.filter(active).length}</span>`:''}</a>`).join('')+`<div class="nav-divider"></div><a href="#account" class="nav-link ${state.view==='account'?'active':''}">${icon('user')}My account</a><a href="#support" class="nav-link ${state.view==='support'?'active':''}">${icon('help')}Help & support</a>`;
$('#profile-name').textContent=api.user?.name||'Welcome to SwiftWash';$('#profile-role').textContent=api.user?`${title(role())} account`:'Sign in to get started';$('#avatar').textContent=initials(api.user?.name);$('.top-avatar').textContent=initials(api.user?.name);$('#connection-label').textContent=api.mode==='demo'?'Demo workspace':'Connected to your API';$('#city-label').textContent=state.city||api.user?.address?.city||'Your neighborhood';$('#page-name').textContent={overview:'Overview',orders:role()==='customer'?'My orders':'Orders',partners:'Find a laundry',saved:'Saved laundries',business:'My business',account:'My account',support:'Help & support'}[state.view]||'Overview';}
async function load(){state.error=null;const results=await Promise.allSettled([api.user?api.listAll('/orders'):Promise.resolve([]),api.listAll('/partners'),api.listAll('/services')]);for(let i=0;i<results.length;i++){if(results[i].status==='fulfilled')state[['orders','partners','services'][i]]=results[i].value;else {state[['orders','partners','services'][i]]=[];state.error=errorText(results[i].reason);}}nav();render();}
function heading(h,p,action=true){return `<div class="page-heading"><div><h1>${h}</h1><p>${p}</p></div>${action&&role()==='customer'?`<button class="button" data-action="book">${icon('plus')}Book a pickup</button>`:''}</div>`;}
function empty(h,p,button='Book a pickup',action='book'){return `<div class="empty-state">${icon('bag')}<h3>${h}</h3><p>${p}</p>${button?`<button class="button" data-action="${action}">${button}</button>`:''}</div>`;}
function timeline(o){const labels=['Order placed','Pickup on the way','In the wash','On its way','Delivered'];const current=o.status==='completed'?5:o.fulfillmentStage==='out_for_delivery'?3:['picked_up','ready_for_delivery'].includes(o.fulfillmentStage)?2:o.fulfillmentStage==='out_for_pickup'?1:0;return `<div class="timeline" aria-label="Order progress: ${esc(title(o.fulfillmentStage))}">${labels.map((s,i)=>`<div class="timeline-step ${i<current?'done':i===current?'current':''}"><span class="step-dot">${i<current?icon('check'):''}</span>${s}</div>`).join('')}</div>`;}
function badge(o){return `<span class="badge ${o.status==='completed'?'green':o.status==='pending'?'orange':o.status==='cancelled'?'red':''}">${o.status==='confirmed'&&o.fulfillmentStage==='out_for_pickup'?'Pickup on the way':o.status==='inprogress'?title(o.fulfillmentStage):title(o.status)}</span>`;}
function orderCard(o,full=true){return `<article class="active-card"><div class="order-card-top"><div class="order-identity"><span class="laundry-icon">${icon('washer')}</span><div><h3>${esc(pName(o.partnerId))}</h3><div class="subline">#${short(o)}<b>•</b>${esc(o.items.map(i=>i.name).join(', '))}</div></div></div>${badge(o)}</div>${full&&o.status!=='cancelled'?timeline(o):'<div style="height:20px"></div>'}<div class="order-card-bottom"><span class="order-schedule">${icon('calendar')}${o.status==='completed'?'Delivered':'Pickup'} <strong>${date(o.status==='completed'?o.deliveryDate:o.pickupDate,true)}</strong></span><button class="text-button" data-action="order" data-id="${o.id}">${o.status==='completed'?'View order':'Track order'} ${icon('arrow')}</button></div></article>`;}
function partnerCard(p,i){const sv=state.services.filter(s=>s.partnerId===p.id&&s.isAvailable);const min=sv.slice().sort((a,b)=>a.price-b.price)[0];const saved=state.saved.includes(p.id);const image=['wash','dry','fold'][i%3];return `<article class="partner-card"><div class="partner-image"><a href="#" data-action="partner" data-id="${p.id}" tabindex="-1" aria-label="${esc(p.businessName)}"><img src="assets/laundry-${image}.svg" alt="${['Freshly folded towels','A freshly cleaned shirt','Carefully folded linens'][i%3]}" loading="lazy"></a><span class="partner-type">${i%3===0?'Everyday favorites':i%3===1?'Expert garment care':'A fresh perspective'}</span><button class="save-button ${saved?'saved':''}" data-action="save" data-id="${p.id}" aria-label="${saved?'Unsave':'Save'} ${esc(p.businessName)}" aria-pressed="${saved}">${icon('heart')}</button></div><div class="partner-body"><div class="partner-title-row"><h3>${esc(p.businessName)}</h3><span class="rating"><span>★</span>${Number(p.rating||0).toFixed(1)}<small>(${p.ratingCount||0})</small></span></div><p class="partner-address">${icon('pin')}${esc(p.location?.street)}, ${esc(p.location?.city)}</p><div class="partner-tags">${[...new Set(sv.map(s=>s.type))].map(t=>`<span class="tag">${{wash:'Wash & fold',dry:'Dry cleaning',fold:'Folding'}[t]||esc(t)}</span>`).join('')||'<span class="tag">Services coming soon</span>'}</div><div class="partner-footer"><span class="price">${min?`From <strong>${money(min.price)}</strong> / ${esc(min.unit)}`:'Explore this laundry'}</span><button class="text-button" data-action="partner" data-id="${p.id}">View laundry ${icon('arrow')}</button></div></div></article>`;}
function dashboard(){const cust=role()==='customer',first=api.user?.name?.split(' ')[0]||'there';const ongoing=state.orders.filter(active);const order=ongoing.find(o=>o.fulfillmentStage==='out_for_pickup')||ongoing[0];return heading(`Hey ${esc(first)}, looking fresh <span class="greeting-star">✦</span>`,cust?"A little less laundry. A little more life. Let's make it happen.":'A fresh view of your orders. Let’s keep everything moving.')+`<section class="hero"><div class="hero-copy"><div class="eyebrow">${icon('sparkles')} LAUNDRY DAY, REIMAGINED</div><h2>${cust?'Your laundry.<br>Our care. <em>Your time.</em>':'Fresh laundry.<br>Happy people. <em>Every day.</em>'}</h2><p>${cust?'Freshly cleaned, neatly folded, and delivered to your door. We’ll take it from here.':'From the first pickup to the final delivery, a little care goes a long way.'}</p><button class="button" data-action="${cust?'book':'view-orders'}">${cust?'Schedule a pickup':'Manage your orders'} ${icon('arrow')}</button></div><span class="hero-spark">✧</span><img src="assets/laundry-scene.svg" class="hero-image" alt="A washing machine, fresh towels, and a basket of laundry"></section><section class="stats" aria-label="Your laundry at a glance">${[['bag','Active orders',ongoing.length,'In good hands'],['check','Completed orders',state.orders.filter(o=>o.status==='completed').length,'Fresh & finished'],['heart','Saved laundries',state.saved.length,'Your favorites']].map(([i,l,v,m])=>`<div class="stat"><span class="stat-icon">${icon(i)}</span><div><p class="stat-label">${l}</p><div class="stat-value">${String(v).padStart(2,'0')}</div></div><span class="stat-meta">${m}</span></div>`).join('')}</section><section><div class="section-heading"><h2>${cust?'Your active order':'Orders in motion'}</h2><a href="#orders" class="text-button">View all orders ${icon('arrow')}</a></div>${order?orderCard(order):empty('A little room for freshness',api.user?'Your next laundry day is one pickup away.':'Sign in to see and manage your orders.',api.user&&cust?'Book your first pickup':api.user?'View orders':'Sign in',api.user&&cust?'book':api.user?'view-orders':'login')}</section><section><div class="section-heading"><div><h2>Laundries you’ll love</h2><p>Good people. Great care. Right in your neighborhood.</p></div><a href="#partners" class="text-button">Explore all ${icon('arrow')}</a></div><div class="partner-grid dashboard-partners">${state.partners.filter(p=>p.isApproved).slice(0,3).map(partnerCard).join('')||empty('Your neighborhood is next','Approved laundry partners will appear here.','','')}</div></section><p class="bottom-note">${icon('shield')}Your clothes are in good hands. Every step of the way.</p>`;}
function ordersView(){let os=state.orders.filter(o=>state.filter==='all'||state.filter==='active'&&active(o)||o.status===state.filter);return heading(role()==='customer'?'Your laundry, at a glance.':'Every order. All in one place.','From the first pickup to the final fold, follow it all here.')+`<div class="toolbar"><div class="tabs" role="group" aria-label="Filter orders">${['all','active','completed','cancelled'].map(t=>`<button class="tab ${state.filter===t?'active':''}" data-action="filter" data-filter="${t}" aria-pressed="${state.filter===t}">${title(t)}${t==='all'?` (${state.orders.length})`:''}</button>`).join('')}</div><button class="text-button" data-action="refresh">Refresh orders ↻</button></div><div class="order-list">${os.map(o=>orderCard(o)).join('')||empty('Nothing in this basket yet','Your orders will appear here as soon as you book.',role()==='customer'?'Book a pickup':'', 'book')}</div>`;}
function partnersView(saved=false){const filtered=state.partners.filter(p=>p.isApproved&&(!saved||state.saved.includes(p.id))&&`${p.businessName} ${p.location?.city} ${p.location?.street}`.toLowerCase().includes(state.search.toLowerCase())&&(state.type==='all'||state.services.some(s=>s.partnerId===p.id&&s.type===state.type))&&(!state.city||String(p.location?.city||'').toLowerCase().includes(state.city.toLowerCase())));return heading(saved?'Good care, on repeat.':'Find your kind of fresh.',saved?'Your favorite neighborhood laundries, all in one place.':'Meet the local experts who make laundry day a little lighter.')+`<div class="toolbar"><div class="tabs" role="group" aria-label="Service type">${[['all','All services'],['wash','Wash & fold'],['dry','Dry cleaning'],['fold','Folding']].map(([t,l])=>`<button class="tab ${state.type===t?'active':''}" data-action="type" data-type="${t}" aria-pressed="${state.type===t}">${l}</button>`).join('')}</div><label class="search-field">${icon('search')}<input id="partner-search" placeholder="Search laundries or neighborhoods" aria-label="Search laundries" value="${esc(state.search)}"></label></div><div id="partner-results" class="partner-grid">${filtered.map(partnerCard).join('')||empty(saved?'Your favorites start here':'No laundries found',saved?'Tap the heart on a laundry to save it for later.':'Try another search, service type, or city.',saved?'Explore laundries':'Clear filters',saved?'explore':'clear-filters')}</div>`;}
function accountView(){if(!api.user)return heading('A fresh start awaits.','Sign in to book a pickup and keep everything in one place.',false)+empty('Make laundry day yours','Create an account, or pick up where you left off.','Sign in','login');const u=api.user;return heading('Make yourself at home.','Your everyday details, taken care of.',false)+`<div class="grid-two"><section class="panel"><h2>Your profile</h2><p>A familiar name and a place to find you.</p><form id="profile-form"><div class="form-grid"><label class="field full">Full name<input name="name" value="${esc(u.name)}" minlength="2" maxlength="100" required></label><label class="field full">Email address<input value="${esc(u.email)}" disabled><small>Your account is registered as a ${esc(u.role)}.</small></label><label class="field full">Street address<input name="street" value="${esc(u.address?.street)}" maxlength="200" placeholder="Street, apartment or suite"></label><label class="field full">City<input name="city" value="${esc(u.address?.city)}" maxlength="100"></label></div><div class="form-actions"><button class="button" type="submit">Save changes</button></div></form></section><div><section class="panel"><h2>Your workspace</h2><p>${api.mode==='demo'?'You’re exploring with sample data. Bookings and changes stay in this browser.':'You’re connected to your SwiftWash API. Bookings and changes are saved on your server.'}</p><button class="button secondary" data-action="connection">${icon('settings')}Connection settings</button></section><section class="panel"><h2>Ready to call it a day?</h2><p>We’ll be here when your laundry needs us.</p><div class="detail-actions"><button class="button secondary" data-action="logout">${icon('logout')}Sign out</button>${api.mode==='demo'?'<button class="button ghost" data-action="switch-role">Explore another role</button>':'<button class="button ghost" data-action="password">Change password</button>'}</div></section></div></div>`;}
function supportView(){return heading('A little help goes a long way.','The details that make laundry day effortless.',false)+`<section class="panel"><h2>Good questions. Fresh answers.</h2>${[['How do I book a pickup?','Choose “Book a pickup”, select a laundry and your services, then choose pickup and delivery dates. Add your address and review the estimate before placing your order.'],['Why is my total an estimate?','Your laundry partner measures the actual weight or number of items after pickup. The final amount is calculated using those quantities and the service prices shown when you booked.'],['Can I change or cancel an order?','You can edit a pending order from its order details. Pending and confirmed orders can be cancelled before pickup. Once laundry is picked up, the order is in progress and cancellation is unavailable.'],['How do I follow my laundry?','Open My orders and choose Track order. You’ll see the current stage, scheduled dates, price breakdown, and the activity history for your order.'],['How do I connect my backend?','Open connection settings at the bottom of the sidebar. Turn off demo mode and enter your Flask API URL. Save the connection, then sign in with an account from your backend. An HTTPS frontend needs an HTTPS backend reachable from your browser.'],['What is demo mode?','Demo mode uses sample records saved in this browser. You can explore bookings and role workflows without connecting a server. No demo booking or profile change is sent to a laundry business.']].map(([q,a])=>`<details class="faq"><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><section class="panel"><h2>Need help with a booking?</h2><p>Open your order details to check the latest activity and your laundry partner’s information.</p><button class="button secondary" data-action="view-orders">View your orders ${icon('arrow')}</button></section>`;}
async function businessView(){if(!['partner','admin'].includes(role()))return;const businessUserId=api.user?.id;state.ownPartner=null;state.ownServices=[];$('#main').innerHTML=heading(role()==='admin'?'A neighborhood of good care.':'Your business, looking fresh.','Manage your laundry profile and the services people love.',false)+`<div id="business-content" class="panel"><div class="loading-state">Loading your workspace…</div></div>`;const content=$('#business-content');const currentView=()=>state.view==='business'&&api.user?.id===businessUserId&&content.isConnected;try {if(role()==='admin'){const ps=await api.listAll('/partners');if(!currentView())return;content.innerHTML=`<h2>Laundry partners</h2><p>Review partner profiles and manage their availability to customers.</p>${ps.map(p=>`<div class="business-row"><div><h3>${esc(p.businessName)}</h3><p>${esc(p.location?.street)}, ${esc(p.location?.city)}</p></div><div class="actions"><span class="badge ${p.isApproved?'green':'orange'}">${p.isApproved?'Approved':'Awaiting approval'}</span><button class="button secondary" data-action="approval" data-id="${p.id}" data-approved="${!p.isApproved}">${p.isApproved?'Revoke approval':'Approve partner'}</button></div></div>`).join('')||'<p>No partner profiles yet.</p>'}`;}else{const ps=await api.listAll('/partners?mine=true');if(!currentView())return;const p=ps.find(p=>p.userId===businessUserId);if(!p){content.innerHTML=`<h2>Let’s introduce your laundry.</h2><p>Create your partner profile, then add your services. An administrator will review your profile.</p><button class="button" data-action="business-profile">Create business profile</button>`;return;}state.ownPartner=p;const sv=await api.listAll(`/partners/${p.id}/services`);if(!currentView())return;content.innerHTML=`<div class="section-heading"><div><h2>${esc(p.businessName)}</h2><p>${esc(p.location.street)}, ${esc(p.location.city)}</p></div><span class="badge ${p.isApproved?'green':'orange'}">${p.isApproved?'Approved':'Awaiting approval'}</span></div><p>${esc(p.description)}</p><button class="button secondary" data-action="business-profile">Edit profile</button><div class="section-heading" style="margin-top:32px"><h2>Your services</h2><button class="button ghost" data-action="service-form">${icon('plus')}Add service</button></div>${sv.map(s=>`<div class="business-row"><div><h3>${esc(s.name)}</h3><p>${money(s.price)} / ${esc(s.unit)} · ${s.isAvailable?'Available':'Unavailable'}</p></div><div class="actions"><button class="text-button" data-action="service-form" data-id="${s.id}">Edit</button><button class="text-button" data-action="delete-service" data-id="${s.id}">Delete</button></div></div>`).join('')||'<p>No services yet. Add your first one.</p>'}`;state.ownServices=sv;}}catch(e){if(!currentView())return;content.innerHTML=`<p class="form-error">${esc(errorText(e))}</p>`;}}
function render(){if(state.view==='business'&&!['partner','admin'].includes(role()))state.view='account';nav();if(state.view==='business'){businessView();return;}$('#main').innerHTML=(state.error?`<div class="form-error">${esc(state.error)} <button class="text-button" data-action="connection">Check connection</button></div>`:'')+({overview:dashboard,orders:ordersView,partners:()=>partnersView(false),saved:()=>partnersView(true),account:accountView,support:supportView}[state.view]||dashboard)();}
function route(){const v=location.hash.slice(1)||'overview';state.view=['overview','orders','partners','saved','account','support','business'].includes(v)?v:'overview';state.search='';$('#sidebar').classList.remove('open');render();window.scrollTo(0,0);}
function modal(h,sub,content,footer='',wide=false){if(!$('.modal'))lastFocus=document.activeElement;$('.app-shell').inert=true;document.body.style.overflow='hidden';$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><div><h2 id="modal-title">${h}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('x')}</button></div><div class="modal-body">${content}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;setTimeout(()=>$('.modal input:not([type=checkbox]),.modal select,.modal button')?.focus(),40);}
function closeModal(){ $('#modal-root').innerHTML='';$('.app-shell').inert=false;document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus?.();lastFocus=null;}
function modalError(e){const container=$('.modal-body');if(!container){toast(errorText(e),true);return;}container.querySelector('.form-error')?.remove();const el=document.createElement('div');el.className='form-error';el.setAttribute('role','alert');el.textContent=errorText(e);container.prepend(el);el.scrollIntoView({block:'nearest'});}
function openConnection(){modal('Your connection','A fresh workspace, your way.',`<div class="connection-note">${icon('info')}Demo mode is a local preview. Connect your Flask backend to use real accounts, laundry partners, and orders.</div><form id="connection-form"><label class="check-field"><input type="checkbox" name="demo" ${api.mode==='demo'?'checked':''}> Use demo mode</label><label class="field full" style="margin-top:23px">API base URL<input type="url" name="baseUrl" value="${esc(api.baseUrl)}" required placeholder="https://api.example.com/api/v1"><small>Use your server origin or a full /api/v1 URL. Hosted HTTPS pages require an HTTPS API.</small></label><div class="form-actions"><button type="button" class="button secondary" data-action="close">Cancel</button><button type="submit" class="button">Save connection</button></div></form>`);}
function openAuth(register=false){modal(register?'A fresh start.':'Welcome back.','A little less laundry starts right here.',`${api.mode==='demo'?`<div class="connection-note">${icon('sparkles')}Demo accounts: customer@swiftwash.demo, partner@swiftwash.demo, rider@swiftwash.demo, or admin@swiftwash.demo. Use any nonempty password.</div>`:''}<form id="auth-form" data-register="${register}"><div class="form-grid">${register?'<label class="field full">Full name<input name="name" autocomplete="name" minlength="2" maxlength="100" required></label><label class="field full">I’m joining as<select name="role"><option value="customer">A customer</option><option value="partner">A laundry partner</option><option value="rider">A delivery rider</option></select></label>':''}<label class="field full">Email address<input name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label><label class="field full">Password<input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" ${register?'minlength="8" maxlength="128"':''} required></label></div><div class="form-actions"><button class="button" type="submit">${register?'Create account':'Sign in'} ${icon('arrow')}</button></div></form><p class="auth-switch">${register?'Already part of the neighborhood?':'New around here?'}<button class="text-button" data-action="${register?'login':'register'}">${register?'Sign in':'Create an account'}</button></p>`);}
async function openPartner(id){try{const p=state.partners.find(p=>p.id===id)||await api.request(`/partners/${id}`);const [sv,rv]=await Promise.all([api.listAll(`/partners/${id}/services`),api.listAll(`/partners/${id}/reviews`)]);modal(esc(p.businessName),`${esc(p.location.street)}, ${esc(p.location.city)}`,`<div class="section-heading"><span class="rating"><span>★</span>${Number(p.rating).toFixed(1)} <small>(${p.ratingCount} reviews)</small></span><span class="pill-label">Approved laundry partner</span></div><p class="muted">${esc(p.description||'Care for the clothes you love.')}</p><div class="detail-section" style="margin-top:25px"><h3>A little care for everything</h3>${sv.map(s=>`<div class="service-choice"><span class="service-symbol">${icon(s.type==='dry'?'shirt':'washer')}</span><div class="service-info"><h3>${esc(s.name)}</h3><p>${esc(title(s.type))} · ${esc(s.unit)}</p></div><strong class="small">${money(s.price)}</strong></div>`).join('')||'<p class="muted">This laundry hasn’t added services yet.</p>'}</div><div class="detail-section"><h3>From the neighborhood</h3>${rv.length?rv.map(r=>`<div class="notification-row"><span class="rating"><span>★</span>${r.rating}</span><p>${esc(r.comment||'A fresh experience.')}</p></div>`).join(''):`<p class="muted">${p.ratingCount?'Customer rating shown above.':'No written reviews yet. Be the first after your order.'}</p>`}</div>`,`<span class="note">Thoughtful care, from pickup to delivery.</span>${role()==='customer'?`<button class="button" data-action="book" data-id="${p.id}" ${sv.length?'':'disabled'}>Book a pickup ${icon('arrow')}</button>`:'<button class="button secondary" data-action="close">Close</button>'}`);}catch(e){toast(errorText(e),true);}}
function localInput(d){const n=new Date(d);return new Date(n.getTime()-n.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function openBooking(id,edit=null){if(!api.user){openAuth();return;}if(role()!=='customer'&&!(role()==='admin'&&edit)){toast('Customer accounts can book pickups. Explore your orders to manage laundry.');return;}const candidates=state.partners.filter(p=>p.isApproved&&state.services.some(s=>s.partnerId===p.id&&s.isAvailable));if(!candidates.length){toast('No laundry services are available for booking yet.');return;}const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);tomorrow.setHours(10,0,0,0);const delivery=new Date(tomorrow);delivery.setDate(delivery.getDate()+2);booking={step:1,partnerId:id||edit?.partnerId||candidates[0].id,quantities:edit?Object.fromEntries(edit.items.map(i=>[i.serviceId,i.estimatedQuantity])):{},pickupDate:localInput(edit?.pickupDate||tomorrow),deliveryDate:localInput(edit?.deliveryDate||delivery),street:edit?.pickupAddress?.street||api.user.address?.street||'',city:edit?.pickupAddress?.city||api.user.address?.city||'',deliveryStreet:edit?.deliveryAddress?.street||'',deliveryCity:edit?.deliveryAddress?.city||'',instructions:edit?.specialInstructions||'',edit};renderBooking();}
function bookingItems(){return state.services.filter(s=>s.partnerId===booking.partnerId&&s.isAvailable&&Number(booking.quantities[s.id])>0);}
function bookingTotal(){return bookingItems().reduce((n,s)=>n+s.price*Number(booking.quantities[s.id]),0);}
function renderBooking(){const b=booking;const sv=state.services.filter(s=>s.partnerId===b.partnerId&&s.isAvailable);const steps=`<div class="booking-steps">${['Your laundry','The details','One last look'].map((l,i)=>`<span class="${b.step===i+1?'active':''}"><i>${i+1}</i>${l}</span>`).join('')}</div>`;let content='';if(b.step===1){content=`<label class="field">Choose your laundry<select id="booking-partner" ${b.edit?'disabled':''}>${state.partners.filter(p=>p.isApproved&&state.services.some(s=>s.partnerId===p.id&&s.isAvailable)).map(p=>`<option value="${p.id}" ${p.id===b.partnerId?'selected':''}>${esc(p.businessName)}</option>`).join('')}</select></label><p class="note">Choose your services and estimated quantities. Your partner will confirm the actual quantities after pickup.</p>${sv.map(s=>`<div class="service-choice"><span class="service-symbol">${icon(s.type==='dry'?'shirt':'washer')}</span><div class="service-info"><h3>${esc(s.name)}</h3><p>${money(s.price)} / ${esc(s.unit)}</p></div><div class="quantity-control"><button type="button" data-action="quantity" data-id="${s.id}" data-delta="-${s.unit==='kg'?'.5':'1'}" aria-label="Decrease ${esc(s.name)}">−</button><input type="number" min="0" max="1000" step="${s.unit==='kg'?'.5':'1'}" data-quantity="${s.id}" value="${b.quantities[s.id]||0}" aria-label="${esc(s.name)} quantity in ${s.unit}"><button type="button" data-action="quantity" data-id="${s.id}" data-delta="${s.unit==='kg'?'.5':'1'}" aria-label="Increase ${esc(s.name)}">+</button></div></div>`).join('')}<div class="estimate"><span>Estimated total</span><strong id="booking-total">${money(bookingTotal())}</strong></div>`;}else if(b.step===2){content=`<form id="booking-details"><div class="form-grid"><label class="field">Pickup date & time<input name="pickupDate" type="datetime-local" value="${b.pickupDate}" min="${localInput(new Date())}" required></label><label class="field">Delivery date & time<input name="deliveryDate" type="datetime-local" value="${b.deliveryDate}" min="${b.pickupDate}" required></label><label class="field full">Pickup street address<input name="street" value="${esc(b.street)}" placeholder="Street, apartment or suite" maxlength="200" required></label><label class="field full">Pickup city<input name="city" value="${esc(b.city)}" maxlength="100" required></label><label class="field">Delivery street address<input name="deliveryStreet" value="${esc(b.deliveryStreet)}" placeholder="Same as pickup" maxlength="200"></label><label class="field">Delivery city<input name="deliveryCity" value="${esc(b.deliveryCity)}" placeholder="Same as pickup" maxlength="100"></label><label class="field full">A little extra care?<textarea name="instructions" maxlength="500" placeholder="Gate code, garment instructions, or anything we should know…">${esc(b.instructions)}</textarea></label></div></form><p class="note">Dates are in your local timezone. Leave both delivery address fields empty to use your pickup address.</p>`;}else {content=`<div class="detail-section"><h3>${esc(pName(b.partnerId))}</h3>${bookingItems().map(s=>`<div class="summary-line"><span>${esc(s.name)} · ${b.quantities[s.id]} ${esc(s.unit)}</span><strong>${money(s.price*b.quantities[s.id])}</strong></div>`).join('')}</div><div class="summary-line"><span>Pickup</span><strong>${date(b.pickupDate,true)}</strong></div><div class="summary-line"><span>Delivery</span><strong>${date(b.deliveryDate,true)}</strong></div><div class="summary-line"><span>Pickup address</span><strong>${esc(b.street)}, ${esc(b.city)}</strong></div><div class="summary-line"><span>Delivery address</span><strong>${esc(b.deliveryStreet||b.street)}, ${esc(b.deliveryCity||b.city)}</strong></div>${b.instructions?`<div class="summary-line"><span>Instructions</span><strong>${esc(b.instructions)}</strong></div>`:''}<div class="estimate"><span>Estimated total</span><strong>${money(bookingTotal())}</strong></div><p class="note">Final pricing is based on actual quantities recorded by your laundry partner. No payment is collected by this booking form.${api.mode==='demo'?' This is a demo booking saved only in this browser.':''}</p>`;}modal(b.edit?'A little change of plans.':'Let’s lighten your load.',b.edit?'Update your pending order.':'Fresh laundry is a few simple steps away.',steps+content,`<button class="button secondary" data-action="${b.step===1?'close':'booking-back'}">${b.step===1?'Cancel':'Back'}</button><button class="button" id="booking-next" ${b.step===2?'type="submit" form="booking-details"':'type="button" data-action="booking-next"'}>${b.step===3?b.edit?'Save changes':'Book my pickup':'Continue'} ${icon('arrow')}</button>`);}
async function bookingNext(btn){try{const b=booking;if(b.step===1){if(Object.values(b.quantities).some(q=>!Number.isFinite(Number(q))||Number(q)<0||Number(q)>1000))throw Error('Quantities must be between 0 and 1,000.');if(!bookingItems().length)throw Error('Choose at least one service to continue.');for(const s of bookingItems()){const q=Number(b.quantities[s.id]);if(!Number.isFinite(q)||q<.5||(s.unit!=='kg'&&!Number.isInteger(q)))throw Error(`Enter a valid quantity for ${s.name}.`);}b.step++;renderBooking();}else if(b.step===2){const f=$('#booking-details');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));if(!Number.isFinite(Date.parse(d.pickupDate))||!Number.isFinite(Date.parse(d.deliveryDate))||Date.parse(d.pickupDate)<=Date.now()||Date.parse(d.deliveryDate)<=Date.parse(d.pickupDate))throw Error('Choose a future pickup time and a delivery time after pickup.');if(!d.street.trim()||!d.city.trim())throw Error('Pickup street and city are required.');if(Boolean(d.deliveryStreet.trim())!==Boolean(d.deliveryCity.trim()))throw Error('Enter both delivery street and city, or leave both empty.');for(const k of ['street','city','deliveryStreet','deliveryCity'])d[k]=d[k].trim();Object.assign(b,d);b.step++;renderBooking();}else{btn.disabled=true;btn.textContent='Booking…';const payload={partnerId:b.partnerId,items:bookingItems().map(s=>({serviceId:s.id,estimatedQuantity:Number(b.quantities[s.id])})),pickupDate:new Date(b.pickupDate).toISOString(),deliveryDate:new Date(b.deliveryDate).toISOString(),pickupAddress:{street:b.street.trim(),city:b.city.trim()},deliveryAddress:{street:(b.deliveryStreet||b.street).trim(),city:(b.deliveryCity||b.city).trim()},specialInstructions:b.instructions};const order=await api.request(b.edit?`/orders/${b.edit.id}`:'/orders',{method:b.edit?'PUT':'POST',body:payload});closeModal();toast(b.edit?'Your order has been updated.':'You’re all booked. A fresher day is on its way.');await load();location.hash='orders';openOrder(order.id);}}catch(e){modalError(e);btn.disabled=false;if(booking?.step===3)btn.innerHTML=`${booking.edit?'Save changes':'Book my pickup'} ${icon('arrow')}`;}}
async function openOrder(id){try{const o=await api.request(`/orders/${id}`);state.currentOrder=o;const staff=['partner','admin'].includes(role());const r=role();let buttons='';if(o.status==='pending'&&(r==='customer'||r==='admin'))buttons+=`<button class="button secondary" data-action="edit-order" data-id="${id}">Edit order</button>`;if(o.status==='pending'&&staff)buttons+=`<button class="button" data-action="set-status" data-id="${id}" data-status="confirmed">Confirm order</button>`;if(['pending','confirmed'].includes(o.status)&&r!=='rider')buttons+=`<button class="button danger" data-action="cancel-order" data-id="${id}">Cancel order</button>`;if(staff&&['confirmed','inprogress'].includes(o.status)&&(!['out_for_pickup','out_for_delivery'].includes(o.fulfillmentStage)||r==='admin'))buttons+=`<button class="button secondary" data-action="assign" data-id="${id}">${o.riderId?'Reassign':'Assign'} rider</button>`;if(staff&&o.status==='inprogress'&&o.fulfillmentStage==='picked_up')buttons+=`<button class="button secondary" data-action="quantities" data-id="${id}">Record actual quantities</button>`;const stages=['not_started','out_for_pickup','picked_up','ready_for_delivery','out_for_delivery','delivered'];const next=stages[stages.indexOf(o.fulfillmentStage)+1];if(active(o)&&next&&(r==='admin'||next==='ready_for_delivery'&&staff||next!=='ready_for_delivery'&&r==='rider')&&(next!=='out_for_pickup'||o.status==='confirmed'))buttons+=`<button class="button" data-action="stage" data-id="${id}" data-stage="${next}">${{out_for_pickup:'Start pickup',picked_up:'Confirm pickup',ready_for_delivery:'Ready for delivery',out_for_delivery:'Start delivery',delivered:'Confirm delivery'}[next]}</button>`;if(o.status==='completed'&&r==='customer')buttons+=`<button class="button" data-action="review" data-id="${id}">Leave a review</button>`;if(['pending','cancelled'].includes(o.status)&&['customer','admin'].includes(r))buttons+=`<button class="button secondary" data-action="delete-order" data-id="${id}">Delete order</button>`;modal(`#${short(o)}`,esc(pName(o.partnerId)),`${badge(o)}${o.status!=='cancelled'?timeline(o):''}<div class="detail-section"><h3>In your laundry bag</h3>${o.items.map(i=>`<div class="summary-line"><span>${esc(i.name)}<br><small>${i.actualQuantity??i.estimatedQuantity} ${esc(i.unit)} ${i.actualQuantity===null?'estimated':''} × ${money(i.unitPrice)}</small></span><strong>${money(i.subtotal)}</strong></div>`).join('')}<div class="estimate"><span>${o.finalTotal===null?'Estimated':'Final'} total</span><strong>${money(o.totalPrice)}</strong></div></div><div class="detail-section"><h3>The little details</h3><div class="summary-line"><span>Pickup</span><strong>${date(o.pickupDate,true)}<br>${esc(o.pickupAddress?.street)}, ${esc(o.pickupAddress?.city)}</strong></div><div class="summary-line"><span>Delivery</span><strong>${date(o.deliveryDate,true)}<br>${esc(o.deliveryAddress?.street)}, ${esc(o.deliveryAddress?.city)}</strong></div>${o.specialInstructions?`<div class="summary-line"><span>Instructions</span><strong>${esc(o.specialInstructions)}</strong></div>`:''}</div><div class="detail-section"><h3>A little progress, every step</h3>${[...(o.statusHistory||[])].reverse().map(h=>`<div class="history-item"><strong>${h.note?esc(h.note):`${esc(title(h.kind))}: ${esc(title(h.to))}`}</strong><p>${esc(h.updatedBy?.name||'SwiftWash')} · ${date(h.timestamp,true)}</p></div>`).join('')}</div>${buttons?`<div class="detail-actions">${buttons}</div>`:''}`,`<span class="note">${api.mode==='demo'?'Demo order · saved in this browser':'Your laundry, in good hands.'}</span><button class="button secondary" data-action="close">Close</button>`,true);}catch(e){toast(errorText(e),true);}}
function confirmAction(h,p,action,id){modal(h,'',`<p class="muted">${p}</p>`,`<button class="button secondary" data-action="order" data-id="${id}">Keep order</button><button class="button danger" data-action="${action}" data-id="${id}">Yes, ${action==='confirm-cancel'?'cancel':'delete'} order</button>`);}
async function updateOrder(id,action,body){await api.request(`/orders/${id}/${action}`,{method:'PATCH',body});await load();await openOrder(id);toast('Your order has been updated.');}
async function openAssign(id){const riders=await api.listAll('/riders');modal('A friendly face for your pickup.','Choose an available rider for this order.',`<form id="assign-form" data-id="${id}"><label class="field">Rider<select name="riderId" required><option value="">Choose a rider</option>${riders.map(r=>`<option value="${r.id}" ${r.isAvailable?'':'disabled'}>${esc(r.name)} · ${r.isAvailable?'Available':'On a trip'} (${r.activeOrderCount} active)</option>`).join('')}</select></label><div class="form-actions"><button class="button" type="submit">Assign rider</button></div></form>`);}
function openQuantities(id){const o=state.currentOrder;modal('A perfect measure.','Record actual quantities to confirm the final price.',`<form id="quantities-form" data-id="${id}"><div class="form-grid">${o.items.map(i=>`<label class="field full">${esc(i.name)} (${esc(i.unit)})<input type="number" name="${i.id}" min="${i.unit==='kg'?'.1':'1'}" step="${i.unit==='kg'?'.1':'1'}" value="${i.actualQuantity??i.estimatedQuantity}" required></label>`).join('')}</div><div class="form-actions"><button class="button" type="submit">Save actual quantities</button></div></form>`);}
function openReview(id){modal('How fresh was your experience?','A little feedback helps your neighborhood laundry shine.',`<form id="review-form" data-id="${id}"><div class="form-grid"><label class="field full">Your rating<select name="rating"><option value="5">★★★★★ · Loved it</option><option value="4">★★★★☆ · Really good</option><option value="3">★★★☆☆ · It was okay</option><option value="2">★★☆☆☆ · Could be better</option><option value="1">★☆☆☆☆ · Disappointed</option></select></label><label class="field full">Tell us a little more<textarea name="comment" maxlength="1000" placeholder="What made the difference?"></textarea></label></div><div class="form-actions"><button class="button" type="submit">Share your review</button></div></form>`);}
function businessForm(){const p=state.ownPartner;modal(p?'The story of your laundry.':'Meet your neighborhood.','Your business profile.',`<form id="business-form"><div class="form-grid"><label class="field full">Business name<input name="businessName" value="${esc(p?.businessName)}" minlength="2" maxlength="120" required></label><label class="field full">Description<textarea name="description" maxlength="500">${esc(p?.description)}</textarea></label><label class="field full">Street address<input name="street" value="${esc(p?.location?.street)}" required></label><label class="field full">City<input name="city" value="${esc(p?.location?.city)}" required></label></div><div class="form-actions"><button class="button" type="submit">Save profile</button></div></form>`);}
function serviceForm(id){const s=state.ownServices?.find(s=>s.id===id);modal(s?'A little service update.':'Add a little more care.','Set up a service for your laundry.',`<form id="service-form" data-id="${id||''}"><div class="form-grid"><label class="field full">Service name<input name="name" value="${esc(s?.name)}" minlength="2" maxlength="100" required></label><label class="field">Type<select name="type">${['wash','dry','fold'].map(t=>`<option value="${t}" ${s?.type===t?'selected':''}>${title(t)}</option>`).join('')}</select></label><label class="field">Unit<select name="unit">${['kg','piece','load'].map(t=>`<option value="${t}" ${s?.unit===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field full">Price per unit (USD)<input name="price" type="number" min="0" step=".01" value="${s?.price??''}" required></label><label class="check-field"><input type="checkbox" name="isAvailable" ${s?.isAvailable!==false?'checked':''}>Available to book</label></div><div class="form-actions"><button class="button" type="submit">Save service</button></div></form>`);}
const actions={
close:()=>closeModal(),menu:()=>$('#sidebar').classList.toggle('open'),account:()=>location.hash='account',explore:()=>location.hash='partners','view-orders':()=>location.hash='orders',connection:openConnection,login:()=>openAuth(false),register:()=>openAuth(true),book:e=>openBooking(e.dataset.id),order:e=>openOrder(e.dataset.id),partner:e=>openPartner(e.dataset.id),
filter:e=>{state.filter=e.dataset.filter;render();},type:e=>{state.type=e.dataset.type;render();},'clear-filters':()=>{state.type='all';state.search='';state.city='';localStorage.removeItem('sw.city');render();},
save:e=>{const id=e.dataset.id;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];localStorage.setItem('sw.saved',JSON.stringify(state.saved));render();},
refresh:async()=>{await load();toast('All fresh. Your orders are up to date.');},
location:()=>modal('A little closer to home.','Find laundry care in your neighborhood.',`<form id="location-form"><label class="field">Your city<input name="city" placeholder="All neighborhoods" value="${esc(state.city)}"><small>Leave empty to explore every city.</small></label><div class="form-actions"><button class="button" type="submit">Find my neighborhood</button></div></form>`),
notifications:()=>modal('A little update for you.','The latest from your laundry bag.',state.orders.filter(active).length?state.orders.filter(active).map(o=>`<div class="notification-row"><span class="service-symbol">${icon('bag')}</span><div><strong class="small">${esc(pName(o.partnerId))}</strong><p>#${short(o)} · ${title(o.fulfillmentStage==='not_started'?o.status:o.fulfillmentStage)}</p><button class="text-button" style="margin-top:8px" data-action="order" data-id="${o.id}">View order →</button></div></div>`).join(''):'<p class="muted">You’re all caught up. Updates about active orders will appear here.</p>'),
logout:async()=>{api.logout();state.ownPartner=null;closeModal();await load();location.hash='account';toast('You’ve been signed out. See you soon.');},'switch-role':()=>openAuth(),
quantity:e=>{const id=e.dataset.id;booking.quantities[id]=Math.max(0,Math.min(1000,(Number(booking.quantities[id])||0)+Number(e.dataset.delta)));renderBooking();},'booking-back':()=>{if(booking.step===2){const f=$('#booking-details');if(f)Object.assign(booking,Object.fromEntries(new FormData(f)));}booking.step--;renderBooking();},'booking-next':bookingNext,
'edit-order':()=>openBooking(null,state.currentOrder),
'cancel-order':e=>confirmAction('Change of plans?','Cancelling this order stops this pickup. You can always book a fresh one when you’re ready.','confirm-cancel',e.dataset.id),
'confirm-cancel':e=>updateOrder(e.dataset.id,'status',{status:'cancelled',note:'Order cancelled.'}),
'delete-order':e=>confirmAction('Empty this one from your basket?','This permanently removes the order from your account.','confirm-delete',e.dataset.id),
'confirm-delete':async e=>{await api.request(`/orders/${e.dataset.id}`,{method:'DELETE'});closeModal();await load();toast('Order deleted.');},
'set-status':e=>updateOrder(e.dataset.id,'status',{status:e.dataset.status}),stage:e=>updateOrder(e.dataset.id,'fulfillment',{stage:e.dataset.stage}),assign:e=>openAssign(e.dataset.id),quantities:e=>openQuantities(e.dataset.id),review:e=>openReview(e.dataset.id),
'business-profile':businessForm,'service-form':e=>serviceForm(e.dataset.id),
'delete-service':e=>modal('Remove this service?','',`<p class="muted">This service will no longer be available to book. Services used by active orders cannot be removed.</p>`,`<button class="button secondary" data-action="close">Keep service</button><button class="button danger" data-action="confirm-delete-service" data-id="${e.dataset.id}">Delete service</button>`),
'confirm-delete-service':async e=>{await api.request(`/services/${e.dataset.id}`,{method:'DELETE'});closeModal();await load();toast('Service removed.');},
approval:async e=>{await api.request(`/partners/${e.dataset.id}/approval`,{method:'PATCH',body:{isApproved:e.dataset.approved==='true'}});await load();toast('Partner approval updated.');},
password:()=>modal('A fresh password.','Keep your account yours.',`<form id="password-form"><div class="form-grid"><label class="field full">Current password<input name="currentPassword" type="password" autocomplete="current-password" required></label><label class="field full">New password<input name="password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label></div><div class="form-actions"><button class="button" type="submit">Update password</button></div></form>`)
};
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(el){ev.preventDefault();const fn=actions[el.dataset.action];if(!fn||el.disabled)return;const mutating=['booking-next','set-status','confirm-cancel','confirm-delete','stage','approval','confirm-delete-service'].includes(el.dataset.action);const wasDisabled=el.disabled;if(mutating&&el.tagName==='BUTTON')el.disabled=true;try{await fn(el);}catch(e){if($('.modal'))modalError(e);else toast(errorText(e),true);}finally{if(mutating&&el.tagName==='BUTTON')el.disabled=wasDisabled;}}else if(ev.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('input',ev=>{if(ev.target.id==='partner-search'){const pos=ev.target.selectionStart;state.search=ev.target.value;$('#main').innerHTML=partnersView(state.view==='saved');$('#partner-search').focus();$('#partner-search').setSelectionRange(pos,pos);}if(ev.target.dataset.quantity){booking.quantities[ev.target.dataset.quantity]=Number(ev.target.value);$('#booking-total').textContent=money(bookingTotal());}});
document.addEventListener('change',ev=>{if(ev.target.id==='booking-partner'){booking.partnerId=ev.target.value;booking.quantities={};renderBooking();}});
document.addEventListener('keydown',ev=>{if(!$('.modal'))return;if(ev.key==='Escape'){closeModal();return;}if(ev.key==='Tab'){const focusables=$$('.modal button:not(:disabled),.modal input:not(:disabled),.modal select:not(:disabled),.modal textarea,.modal a').filter(e=>e.offsetParent!==null);const first=focusables[0],last=focusables.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}});
document.addEventListener('submit',async ev=>{const form=ev.target;if(!form.id)return;ev.preventDefault();if(form.id==='booking-details'){const next=$('#booking-next');if(next&&!next.disabled)await bookingNext(next);return;}const data=Object.fromEntries(new FormData(form)),button=form.querySelector('[type=submit]');button?.setAttribute('disabled','');try{switch(form.id){
case 'connection-form':api.configure({baseUrl:data.baseUrl,demo:!!data.demo});state.ownPartner=null;closeModal();await load();toast(api.mode==='demo'?'Demo workspace ready.':'API connection saved. Sign in to get started.');if(api.mode!=='demo')openAuth();break;
case 'auth-form':if(form.dataset.register==='true')await api.register(data);else await api.login(data.email,data.password);state.ownPartner=null;closeModal();await load();location.hash='overview';toast(`Welcome ${api.user.name.split(' ')[0]}. Make yourself at home.`);break;
case 'profile-form':{if(Boolean(data.street.trim())!==Boolean(data.city.trim()))throw Error('Please enter both street and city.');const payload={name:data.name};if(data.street.trim())payload.address={street:data.street.trim(),city:data.city.trim()};await api.request(`/users/${api.user.id}`,{method:'PATCH',body:payload});await api.restore();render();toast('Your profile is all up to date.');break;}
case 'location-form':state.city=data.city.trim();localStorage.setItem('sw.city',state.city);closeModal();location.hash='partners';render();break;
case 'assign-form':await updateOrder(form.dataset.id,'rider',{riderId:data.riderId});break;
case 'quantities-form':await updateOrder(form.dataset.id,'actual-quantities',{items:Object.entries(data).map(([itemId,q])=>({itemId,actualQuantity:Number(q)}))});break;
case 'review-form':await api.request('/reviews',{method:'POST',body:{orderId:form.dataset.id,rating:Number(data.rating),comment:data.comment}});closeModal();await load();toast('Thanks for sharing a little love for your laundry.');break;
case 'business-form':{const p=state.ownPartner;await api.request(p?`/partners/${p.id}`:'/partners',{method:p?'PUT':'POST',body:{businessName:data.businessName,description:data.description,location:{street:data.street,city:data.city}}});closeModal();await load();toast('Business profile saved.');break;}
case 'service-form':{await api.request(form.dataset.id?`/services/${form.dataset.id}`:'/services',{method:form.dataset.id?'PUT':'POST',body:{...data,price:Number(data.price),isAvailable:!!data.isAvailable}});closeModal();await load();toast('Service saved. Fresh possibilities ahead.');break;}
case 'password-form':await api.request(`/users/${api.user.id}`,{method:'PATCH',body:data});closeModal();toast('Your password has been updated.');break;
}}catch(e){if($('.modal'))modalError(e);else toast(errorText(e),true);}finally{button?.removeAttribute('disabled');}});
window.addEventListener('hashchange',route);
hydrate();
try {await api.restore();}catch(e){toast(errorText(e),true);}
state.view=location.hash.slice(1)||'overview';await load();
